import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, csvToMarkdownTable } from './convert.mjs';

test('parseCsv splits plain rows on commas', () => {
  assert.deepEqual(parseCsv('a,b,c\n1,2,3\n'), [['a', 'b', 'c'], ['1', '2', '3']]);
});

test('parseCsv keeps a comma inside a quoted field intact', () => {
  assert.deepEqual(parseCsv('name,city\nAda,"New York, NY"\n'), [['name', 'city'], ['Ada', 'New York, NY']]);
});

test('parseCsv unescapes a doubled quote inside a quoted field', () => {
  assert.deepEqual(parseCsv('quote\n"she said ""hi"""\n'), [['quote'], ['she said "hi"']]);
});

test('parseCsv keeps a newline inside a quoted field as part of the field', () => {
  assert.deepEqual(parseCsv('a\n"line1\nline2"\n'), [['a'], ['line1\nline2']]);
});

test('parseCsv does not add a phantom row for a trailing newline', () => {
  assert.deepEqual(parseCsv('a,b\n1,2\n'), [['a', 'b'], ['1', '2']]);
});

test('parseCsv handles a final row with no trailing newline', () => {
  assert.deepEqual(parseCsv('a,b\n1,2'), [['a', 'b'], ['1', '2']]);
});

test('parseCsv returns no rows for empty input', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('csvToMarkdownTable renders a header, separator, and data rows', () => {
  const md = csvToMarkdownTable('name,age\nAda,36\nGrace,85\n');
  assert.equal(md, '| name | age |\n| --- | --- |\n| Ada | 36 |\n| Grace | 85 |\n');
});

test('csvToMarkdownTable escapes a literal pipe in a cell', () => {
  const md = csvToMarkdownTable('a\nleft|right\n');
  assert.match(md, /left\\\|right/);
});

test('csvToMarkdownTable converts an embedded newline into <br>', () => {
  const md = csvToMarkdownTable('a\n"line1\nline2"\n');
  assert.match(md, /line1<br>line2/);
});

test('csvToMarkdownTable pads a short row with empty cells', () => {
  const md = csvToMarkdownTable('a,b,c\n1,2\n');
  assert.equal(md, '| a | b | c |\n| --- | --- | --- |\n| 1 | 2 |  |\n');
});

test('csvToMarkdownTable truncates a row longer than the header', () => {
  const md = csvToMarkdownTable('a,b\n1,2,3,4\n');
  assert.equal(md, '| a | b |\n| --- | --- |\n| 1 | 2 |\n');
});

test('csvToMarkdownTable throws on empty input', () => {
  assert.throws(() => csvToMarkdownTable(''), /no rows found/);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { writeFileSync, unlinkSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { parseCSV, toMarkdownTable, csvToMarkdownTable } from "./convert.mjs";

const scriptPath = fileURLToPath(new URL("./convert.mjs", import.meta.url));

test("parseCSV splits simple rows into fields", () => {
  const rows = parseCSV("name,age\nAda,36\nGrace,85\n");
  assert.deepEqual(rows, [
    ["name", "age"],
    ["Ada", "36"],
    ["Grace", "85"],
  ]);
});

test("parseCSV handles quoted fields with embedded commas and newlines", () => {
  const rows = parseCSV('name,note\n"Doe, Jane","line one\nline two"\n');
  assert.deepEqual(rows, [
    ["name", "note"],
    ["Doe, Jane", "line one\nline two"],
  ]);
});

test("parseCSV unescapes doubled quotes inside quoted fields", () => {
  const rows = parseCSV('quote\n"She said ""hi"""\n');
  assert.deepEqual(rows, [["quote"], ['She said "hi"']]);
});

test("parseCSV works without a trailing newline", () => {
  const rows = parseCSV("a,b\n1,2");
  assert.deepEqual(rows, [
    ["a", "b"],
    ["1", "2"],
  ]);
});

test("toMarkdownTable renders a GitHub-flavored markdown table", () => {
  const table = toMarkdownTable([
    ["name", "age"],
    ["Ada", "36"],
    ["Grace", "85"],
  ]);
  assert.equal(
    table,
    ["| name | age |", "| --- | --- |", "| Ada | 36 |", "| Grace | 85 |"].join("\n"),
  );
});

test("toMarkdownTable escapes pipe characters and converts newlines to <br>", () => {
  const table = toMarkdownTable([
    ["a", "b"],
    ["1|2", "line one\nline two"],
  ]);
  assert.equal(
    table,
    ["| a | b |", "| --- | --- |", "| 1\\|2 | line one<br>line two |"].join("\n"),
  );
});

test("toMarkdownTable pads short rows and truncates long rows to the header width", () => {
  const table = toMarkdownTable([
    ["a", "b", "c"],
    ["1"],
    ["2", "3", "4", "5"],
  ]);
  assert.equal(
    table,
    ["| a | b | c |", "| --- | --- | --- |", "| 1 |  |  |", "| 2 | 3 | 4 |"].join("\n"),
  );
});

test("toMarkdownTable throws on an empty CSV", () => {
  assert.throws(() => toMarkdownTable(parseCSV("")), /empty CSV/);
});

test("csvToMarkdownTable is the parse+render composition", () => {
  assert.equal(
    csvToMarkdownTable("a,b\n1,2\n"),
    "| a | b |\n| --- | --- |\n| 1 | 2 |",
  );
});

test("CLI reads a CSV file path argument and writes the table to stdout", () => {
  const csvPath = fileURLToPath(new URL("./__fixture.csv", import.meta.url));
  writeFileSync(csvPath, "name,age\nAda,36\n");
  try {
    const output = execFileSync("node", [scriptPath, csvPath], { encoding: "utf8" });
    assert.equal(output, "| name | age |\n| --- | --- |\n| Ada | 36 |\n");
  } finally {
    unlinkSync(csvPath);
  }
});

test("CLI reads CSV from stdin when no file path is given", () => {
  const output = execFileSync("node", [scriptPath], {
    input: "name,age\nAda,36\n",
    encoding: "utf8",
  });
  assert.equal(output, "| name | age |\n| --- | --- |\n| Ada | 36 |\n");
});
